{
  "state_machine": {
    "states": [
      {
        "name": "S0_POWER_UP_INHIBIT",
        "description": "First 5 s after the first FB invocation; alarm is inhibited and gap debounce timing is blocked.",
        "outputs": {
          "Operator_Alert": false,
          "Weld_Soft_Start_Active": true
        },
        "actions": [
          "force alert off",
          "clear gap qualification",
          "keep gap debounce timer reset/disabled"
        ]
      },
      {
        "name": "S1_MONITOR_IDLE",
        "description": "Post-startup, E-stop healthy, gap not exceeded; alarm off and gap debounce reset.",
        "outputs": {
          "Operator_Alert": false,
          "Weld_Soft_Start_Active": false
        },
        "actions": [
          "clear gap qualification",
          "reset gap debounce timing"
        ]
      },
      {
        "name": "S2_GAP_DEBOUNCING",
        "description": "Post-startup, E-stop healthy, gap exceeded; debounce is accumulating.",
        "outputs": {
          "Operator_Alert": false,
          "Weld_Soft_Start_Active": false
        },
        "actions": [
          "accumulate GapDebounceTimer while Gap_Exceeded and E-stop healthy"
        ]
      },
      {
        "name": "S3_GAP_ALARM",
        "description": "Post-startup, E-stop healthy, gap exceeded, and debounce qualified; alarm is on.",
        "outputs": {
          "Operator_Alert": true,
          "Weld_Soft_Start_Active": false
        },
        "actions": [
          "keep Operator_Alert TRUE while Gap_Exceeded, Weld_E_Stop_NC, and gapQualified remain true"
        ]
      },
      {
        "name": "S4_ESTOP_SUPPRESS",
        "description": "Emergency-stop active; highest-priority suppression of alarm and gap debounce.",
        "outputs": {
          "Operator_Alert": false,
          "Weld_Soft_Start_Active": "determined independently by startupActive"
        },
        "actions": [
          "force alert off",
          "clear gap qualification",
          "reset gap debounce timing",
          "do not reset or restart StartupTimer"
        ]
      }
    ],
    "transitions": [
      {
        "from": "S0_POWER_UP_INHIBIT",
        "to": "S4_ESTOP_SUPPRESS",
        "guard": "!Weld_E_Stop_NC",
        "priority": 1,
        "action": "set forceAlertOff; clear gapQualified; request resetGapDebounce; StartupTimer continues"
      },
